leapyear.h<pre><code>#ifndef LEAPYEAR_H
#define LEAPYEAR_H
#include &lt;stdbool.h&gt;

extern bool isLeapYear(int year);
#endif
</code></pre> leapyear.c<pre><code>#include "leapyear.h"

bool isLeapYear(int year) {
    return (year % 4 == 0 &amp;&amp; year % 100 != 0) || year % 400 == 0;
}
</code></pre>

leapyear_test.c<pre><code>#include "leapyear.h"
#include &lt;assert.h&gt;

void testLeapYears(void) {
    assert(isLeapYear(0));
    assert(isLeapYear(4));
    assert(isLeapYear(400));
}

void testNonLeapYears(void) {
    assert(!isLeapYear(1));
    assert(!isLeapYear(100));
}
</code></pre> <p>No includes from AceUnit. Just <code>&lt;assert.h&gt;</code> and the header under test. AceUnit discovers <code>testLeapYears</code> and <code>testNonLeapYears</code> by their names.</p>
